mapper.select:
SELECT auto_transfer_id, withdrawal_account_id, deposit_account_id, money_box_id, deposit_institution_name, masked_deposit_account, transfer_amount, transfer_day, start_date, end_date, auto_transfer_status, created_at, updated_at FROM auto_transfer WHERE auto_transfer_status = 'ACTIVE' AND (
deposit_account_id IN
#{accountId}
OR
money_box_id IN
#{moneyBoxId}
)

SELECT at.auto_transfer_id AS autoTransferId, mb.money_box_id AS moneyBoxId, mb.account_id AS accountId, mb.user_id AS userId, at.transfer_amount AS transferAmount, a.balance - COALESCE((SELECT SUM(other.balance) FROM money_box other WHERE other.account_id = a.account_id), 0) AS availableBalance FROM auto_transfer at JOIN money_box mb ON at.money_box_id = mb.money_box_id JOIN account a ON mb.account_id = a.account_id WHERE at.auto_transfer_status = 'ACTIVE' AND ( at.transfer_day = DAY(#{executionDate}) OR (at.transfer_day > DAY(LAST_DAY(#{executionDate})) AND DAY(#{executionDate}) = DAY(LAST_DAY(#{executionDate}))) )
AND mb.user_id = #{userId}
ORDER BY at.auto_transfer_id
